-- Demo inventory and local CSV datasets for Supabase.
-- Run after 001_initial_schema.sql.
-- This stores generated/training/replay data separately from live operational tables.
-- It does not fabricate live BGP events, alerts, routes, or ROAs.

create table if not exists dataset_rows (
    id bigint generated by default as identity primary key,
    source_file text not null,
    row_number integer not null,
    row_data jsonb not null,
    loaded_at timestamptz not null default now(),
    unique (source_file, row_number)
);

create index if not exists idx_dataset_rows_source
    on dataset_rows (source_file, row_number);

    prefix, expected_origin_asn, max_length, organization, description, status
)
values
    ('192.0.2.0/24'::cidr, 64500, 24, 'BGP Monitor Demo', 'Primary network', 'active'),
    ('198.51.100.0/24'::cidr, 64501, 25, 'BGP Monitor Demo', 'Secondary network', 'active'),
    ('198.51.100.0/24'::cidr, 64502, 25, 'BGP Monitor Demo', 'Secondary network', 'active'),
    ('203.0.113.0/24'::cidr, 64503, 24, 'BGP Monitor Demo', 'Test network', 'active')
on conflict (prefix, expected_origin_asn)
do update set
    max_length = excluded.max_length,
    organization = excluded.organization,
    description = excluded.description,
    status = excluded.status,
    updated_at = now();

delete from dataset_rows where source_file = 'data/processed/test.csv';
on conflict (source_file, row_number) do update set row_data = excluded.row_data, loaded_at = now();

delete from dataset_rows where source_file = 'data/processed/train.csv';
on conflict (source_file, row_number) do update set row_data = excluded.row_data, loaded_at = now();

delete from dataset_rows where source_file = 'data/synthetic/controlled_scenario_log.csv';
on conflict (source_file, row_number) do update set row_data = excluded.row_data, loaded_at = now();

delete from dataset_rows where source_file = 'data/synthetic/controlled_scenarios.csv';
on conflict (source_file, row_number) do update set row_data = excluded.row_data, loaded_at = now();

delete from dataset_rows where source_file = 'data/synthetic/controlled_scenarios_features.csv';
on conflict (source_file, row_number) do update set row_data = excluded.row_data, loaded_at = now();

delete from dataset_rows where source_file = 'data/synthetic/controlled_scenarios_revalidated.csv';
on conflict (source_file, row_number) do update set row_data = excluded.row_data, loaded_at = now();

-- ROA records must come from Routinator/validated VRPs, not the generated CSV datasets.
-- Live BGP events, routing state, anomaly alerts, and ML predictions remain empty
-- until the corresponding ingestion or training workflow is run.

select source_file, count(*) as row_count
from dataset_rows
group by source_file
order by source_file;
